#pragma once
#include <stdint.h>
#include <stdbool.h>

#define E820_MAX_ENTRIES  128u
#define E820_ACPI_ENABLED 0x01u

// E820 Memory Map Entry structure generated by the BIOS
struct mem_map_entry{
    uint64_t base_addr;
    uint64_t region_length;
    uint32_t region_type;
    uint32_t acpi_attributes;
} __attribute__((packed));

typedef struct{
    uint32_t start_frame;
    uint32_t frame_count;
} pmm_alloc_range_t;

void pmm_init(void);
void* pmm_alloc_block(void);
void pmm_free_block(void* physical_addr);

int get_used_memory(void);
int get_total_memory(void);
int get_free_memory(void);

bool pmm_is_usable_block(void *physical_addr);
bool pmm_is_allocated_block(void *physical_addr);

uint32_t pmm_save_allocated_ranges(pmm_alloc_range_t* buffer, uint32_t max_ranges);
void pmm_restore_allocated_ranges(const pmm_alloc_range_t* buffer, uint32_t range_count);